def golomb_ruler(n, max_length=100):
    marks = [0]
    def backtrack():
        if len(marks) == n:
            return True
        for pos in range(marks[-1] + 1, max_length + 1):
            diffs = {pos - m for m in marks}
            all_diffs = set()
            for m in marks:
                for existing in marks:
                    if existing > m:
                        all_diffs.add(existing - m)
            if not diffs & all_diffs:  # no overlap
                # better way
                current_diffs = set()
                conflict = False
                for m in marks:
                    d = pos - m
                    if d in current_diffs:
                        conflict = True
                        break
                    current_diffs.add(d)
                if not conflict:
                    marks.append(pos)
                    if backtrack():
                        return True
                    marks.pop()
        return False
    if backtrack():
        return marks
    return None

result = golomb_ruler(9, 50)
print(result)

def is_golomb(ruler):
    diffs = set()
    for i in range(len(ruler)):
        for j in range(i+1, len(ruler)):
            diff = ruler[j] - ruler[i]
            if diff in diffs:
                return False
            diffs.add(diff)
    return True, len(diffs)

